{
  "title": "A Gentle Sunday in Reykjavik",
  "summary": "A slower day with just two unhurried activities and proper time for meals, keeping the crew's must-do Geysir stop.",
  "stops": [
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one stop we must keep, and with a slower pace we can let the steam and sputter do the talking."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "A cosy vegetarian-friendly lunch, close to the afternoon's gentle wander."
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "A calm climb for the view, and the only other activity today, so there is no rush to leave."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with vegetarian options and a long, lazy table, because a slower day still ends well fed."
    }
  ]
}
